 "file_path": "/workspace/invoice_totals.py",
 "content": """"Sum invoice amounts by customer."""
import csv
from collections import defaultdict
from decimal import ROUND_HALF_UP, Decimal

CENTS = Decimal("0.01")


def totals(path):
    """Return exact per-customer sums as unrounded Decimals.

    Amounts are parsed from their CSV text rather than through float, so a
    value like "1.005" keeps its exact decimal value. Callers round for
    display with round_cents.
    """
    result = defaultdict(lambda: Decimal("0"))
    with open(path, newline="") as source:
        for row in csv.DictReader(source):
            result[row["customer"]] += Decimal(row["amount"])
    return dict(result)


def round_cents(amount):
    """Round a total to two decimal places, half away from zero."""
    return amount.quantize(CENTS, rounding=ROUND_HALF_UP)


if __name__ == "__main__":
    for customer, amount in sorted(totals("invoices.csv").items()):
        print(f"{customer},{round_cents(amount)}")
"
