{
 "file_path": "/workspace/test_invoice_totals.py",
 "content": """"Regression tests for decimal-currency totalling."""
import subprocess
import sys
import tempfile
import unittest
from decimal import Decimal
from pathlib import Path

from invoice_totals import round_cents, totals

HERE = Path(__file__).parent


def write_csv(rows):
    """Write "customer,amount" rows to a temp CSV and return its path."""
    handle = tempfile.NamedTemporaryFile(
        mode="w", suffix=".csv", delete=False, newline=""
    )
    with handle:
        handle.write("customer,amount\n")
        for customer, amount in rows:
            handle.write(f"{customer},{amount}\n")
    return handle.name


class TotalsTest(unittest.TestCase):
    def test_sums_are_exact_not_binary_approximations(self):
        path = write_csv([("Aster", "0.10"), ("Aster", "0.20")])
        # float accumulation gives 0.30000000000000004 here.
        self.assertEqual(totals(path)["Aster"], Decimal("0.30"))

    def test_totals_are_decimals(self):
        path = write_csv([("Aster", "0.10")])
        self.assertIsInstance(totals(path)["Aster"], Decimal)

    def test_totals_are_not_pre_rounded(self):
        path = write_csv([("Birch", "1.005")])
        self.assertEqual(totals(path)["Birch"], Decimal("1.005"))

    def test_groups_by_customer(self):
        path = write_csv(
            [("Aster", "1.00"), ("Birch", "2.00"), ("Aster", "3.00")]
        )
        self.assertEqual(
            totals(path),
            {"Aster": Decimal("4.00"), "Birch": Decimal("2.00")},
        )

    def test_no_drift_over_many_invoices(self):
        path = write_csv([("Aster", "0.01")] * 100)
        # Summing 0.01 a hundred times as floats gives 1.0000000000000007.
        self.assertEqual(totals(path)["Aster"], Decimal("1.00"))

    def test_missing_customer_is_not_autocreated(self):
        path = write_csv([("Aster", "1.00")])
        result = totals(path)
        with self.assertRaises(KeyError):
            result["Nobody"]

    def test_empty_file_has_no_totals(self):
        path = write_csv([])
        self.assertEqual(totals(path), {})


class RoundCentsTest(unittest.TestCase):
    def test_rounds_halves_up_not_to_even(self):
        # Each of these rounds down under round-half-even, which is what
        # f"{value:.2f}" applies.
        for amount, expected in [
            ("0.005", "0.01"),
            ("1.005", "1.01"),
            ("1.025", "1.03"),
            ("2.675", "2.68"),
        ]:
            with self.subTest(amount=amount):
                self.assertEqual(
                    round_cents(Decimal(amount)), Decimal(expected)
                )

    def test_rounds_below_and_above_the_half(self):
        self.assertEqual(round_cents(Decimal("1.004")), Decimal("1.00"))
        self.assertEqual(round_cents(Decimal("1.006")), Decimal("1.01"))

    def test_negative_halves_round_away_from_zero(self):
        self.assertEqual(round_cents(Decimal("-1.005")), Decimal("-1.01"))

    def test_always_two_decimal_places(self):
        for amount, expected in [("5", "5.00"), ("0", "0.00"), ("1.5", "1.50")]:
            with self.subTest(amount=amount):
                self.assertEqual(f"{round_cents(Decimal(amount))}", expected)


class RoundOnlyAfterSummingTest(unittest.TestCase):
    def test_two_halves_do_not_round_up_twice(self):
        path = write_csv([("Aster", "0.005"), ("Aster", "0.005")])
        # Rounding each row first would give 0.01 + 0.01 = 0.02.
        self.assertEqual(round_cents(totals(path)["Aster"]), Decimal("0.01"))

    def test_sub_cent_amounts_accumulate_before_rounding(self):
        path = write_csv([("Aster", "0.004")] * 3)
        # Rounding each row first would give 0.00.
        self.assertEqual(round_cents(totals(path)["Aster"]), Decimal("0.01"))


class ScriptOutputTest(unittest.TestCase):
    def test_fixture_output(self):
        result = subprocess.run(
            [sys.executable, "invoice_totals.py"],
            cwd=HERE,
            capture_output=True,
            text=True,
            check=True,
        )
        self.assertEqual(result.stdout, "Aster,0.30\nBirch,1.01\n")


if __name__ == "__main__":
    unittest.main()
"
